using System; using System.IO; using System.Text; class Program { static void Main() { var root = @"D:\Working Copies\CompressionWorkbench\Compression.Tests\bin\Debug\net10.0\third-party-tools\exe-packers\packing-box\dataset-packed-pe-main\packed"; var packers = new[] { "Amber", "Eronana Packer", "Exe32pack", "FSG", "Molebox", "TELock", "Themida", "WinUpack", "Yoda-Protector" }; foreach (var packer in packers) { var dir = Path.Combine(root, packer); if (!Directory.Exists(dir)) continue; var file = Directory.GetFiles(dir)[0]; var bytes = File.ReadAllBytes(file); Console.WriteLine($"\n--- {packer} ---"); int peHeader = BitConverter.ToInt32(bytes, 0x3C); short numSections = BitConverter.ToInt16(bytes, peHeader + 6); short optHeaderSize = BitConverter.ToInt16(bytes, peHeader + 20); int sectionTable = peHeader + 24 + optHeaderSize; for (int i = 0; i < numSections; i++) { int offset = sectionTable + (i * 40); string name = Encoding.ASCII.GetString(bytes, offset, 8).TrimEnd('\0'); Console.WriteLine($"Section {i}: {name}"); } } } }
